        "210": { n: "Odstupanje od projektne debljine zaštitnog sloja betona", t: "Odstupanje od projektovane debljine zaštitnog sloja betona ne sme prelaziti:\npri debljini zaštitnog sloja do 15 mm i dimenzijama poprečnog preseka konstrukcija do 100 mm – +4 mm; od 101 do 200 mm – +5 mm;\npri debljini zaštitnog sloja od 16 do 20 mm uključivo i dimenzijama poprečnog preseka konstrukcija do 100 mm – +4, -3 mm; od 101 do 200 mm – +8, -3 mm; od 201 do 300 mm – +10, -3 mm; preko 300 mm – +15, -5 mm;\npri debljini zaštitnog sloja preko 20 mm i dimenzijama poprečnog preseka konstrukcija do 100 mm – +4, -5 mm; od 101 do 200 mm – +8, -5 mm; od 201 do 300 mm – +10, -5 mm; preko 300 mm – +15, -5 mm.\nSP 70.13330.2012 tabela 5.10." },
        "211": { n: "Prisustvo rđe, mraza, leda, zagađenje betonom", t: "Rđa, inje, led, zaprljanost betonom, okujina, tragovi ulja, rđa koja se ljušti, kontinualna površinska korozija – nije dozvoljeno. SP 70.13330.2012 tač. 5.16.18." },
        "213": { n: "Broj distancera na m² konstrukcije", t: "Moraju obezbediti debljinu zaštitnog sloja. Minimum 4 kom. na 1 m² konstrukcije." },
        "214": { n: "Ukupan broj šipki po dužnom metru konstrukcije", t: "Prema projektu. SP 70.13330.2012 tabela 5.10." },
        "215": { n: "Odstupanje u rastojanju između redova armature", t: "Za ploče i grede debljine do 1 m – ±10 mm; za konstrukcije debljine veće od 1 m – ±20 mm. SP 70.13330.2012 tabela 5.10." },
        "216": { n: "Odstupanje od projektovanog položaja početka povijanja podužne armature", t: "±20 mm. SP 70.13330.2012 tabela 5.10." },
        "217": { n: "Najmanje dozvoljeno svetlo rastojanje između podužnih šipki", t: "d – prečnik najmanje šipke, mm; osim slučaja nastavljanja šipki i njihovog spajanja u snopove prema projektu: pri horizontalnom ili kosom položaju šipki donje armature – 25 mm; pri horizontalnom ili kosom položaju gornje armature – 30 mm; isto, pri rasporedu donje armature u više od dva reda (osim šipki dva donja reda) – 50 mm; pri vertikalnom položaju šipki – 50 mm, ali ne manje od d; dozvoljeni nivo defektnosti – 5%. SP 70.13330.2012 tabela 5.10." },
        "218": { n: "Nedopustiva neotklonjiva odstupanja od projekta", t: "Usaglašavanje sa projektantskom organizacijom o njihovoj dopustivosti. SP 70.13330.2012 tač. 5.16.17." },
        "219": { n: "Šema vezivanja paljenom žicom", t: "Mora obezbediti očuvanje geometrijskog oblika. Šema vezivanja (svaki presek, šahovski raspored) određuje se projektom, PIR. Žica mora biti savijena ka unutrašnjosti armaturnog koša." },
        "220": { n: "Nedostajući armaturni ispusti posle betoniranja", t: "Detalj usaglašen sa projektantskom organizacijom (hemijski ankeri, zavarivanje)." },
        "221": { n: "Tačnost izrade i montaže oplate", t: "Sučeoni spojevi panela, mm, ne više od – 2 mm; sučeoni spojevi oplatne ploče, mm, ne više od – 2 mm; odstupanje od pravolinijskosti horizontalnih elemenata oplate tavanica na dužini L, mm – L/800; prolazne pukotine u sučeonim spojevima, mm, ne više od – 1 mm; ugib oblikujuće površine montažno-monolitnih konstrukcija i nosećih elemenata oplate pod dejstvom opterećenja pri rasponu L: vertikalnih elemenata – L/300 (klasa 2), horizontalnih elemenata – L/400 (klasa 2). GOST 34329-2017, tabela 1." },
        "222": { n: "Visina slobodnog pada betonske mešavine u oplatu konstrukcije", t: "Ne više od: stubovi – 5,0 m; tavanice – 1,0 m; zidovi – 4,5 m; nearmirane konstrukcije – 6,0 m. SP 70.13330.2012, tabela 5.2." },
        "223": { n: "Gornji nivo ugrađene betonske mešavine", t: "Mora biti niži od vrha panela oplate – 50–70 mm. SP 70.13330.2012, tabela 5.2." },
        "224": { n: "Debljina slojeva betonske mešavine koji se ugrađuju", t: "Pri zbijanju mešavine teškim visećim vertikalno postavljenim vibratorima – za 5–10 cm manje od dužine radnog dela vibratora; pri zbijanju visećim vibratorima postavljenim pod uglom prema vertikali (do 30°) – ne više od vertikalne projekcije dužine radnog dela vibratora; pri zbijanju ručnim pervibratorima – ne više od 1,25 dužine radnog dela vibratora; pri zbijanju površinskim vibratorima u konstrukcijama: nearmiranim – 25 cm; sa jednostrukom armaturom – 55 cm; sa dvostrukom armaturom – 12 cm; sa kompozitnom polimernom armaturom – 12 cm. SP 70.13330.2012, tabela 5.2." },

