        "606": { n: "Čistoća trake za brtvljenje", t: "Hidrotraku pre betoniranja treba temeljno očistiti od prljavštine i leda" },
        "607": { n: "Postavljanje simetrično, u sredinu radnih spojnica", t: "odstupanje od projektnog položaja ≤ 30 mm" },
