        "610": { n: "Kvalitet spojeva, zatvorena kontura", t: "Čvrsta veza elemenata, zatvoren prostor po celom obimu" },
        "611": { n: "Korak postavljanja pričvrsnih elemenata", t: "Od 200 do 250 mm" },
        "612": { n: "Spojevi konstrukcija", t: "Ne manje od 30 mm" },
        "613": { n: "Priprema površine", t: "Traka se postavlja na pripremljenu betonsku površinu pre montaže oplate, u sredini radne spojnice" },
        "614": { n: "Zaptivanje spojeva i uglova", t: "Odozgo preko zavarenog šava navariti PVC traku širine ne manje od 25mm radi zaptivanja i ojačanja sučeonog spoja trake (traka se vari sa obe strane šava)" },
        "615": { n: "Spajanje trake / kvalitet zavarenog šva", t: "Sučeono. Spojevi i uglovi trake se zavaruju specijalnim alatom za zavarivanje. Kontrola prosvetljavanjem. Za proveru se može koristiti elektroiskrni defektoskop" },
        "616": { n: "Celovitost trake", t: "Bez probušenja, zasečenja i sl." },
        "617": { n: "Korak pričvršćivanja za armaturni skelet", t: "200-300 mm" },
        "618": { n: "Rastojanje do armature", t: "≥ 20 mm" },
        "619": { n: "Odstupanje od ose spoja", t: "≤ 10 mm" },
        "620": { n: "Zavijanje ankera trake", t: "≤ 10 mm" },
        "621": { n: "Priprema površine za montažu", t: "Betonska površina mora biti očišćena od prašine, zemlje, leda, boje i drugih stranih materija" },
        "622": { n: "Dužina postavljenog segmenta", t: "≤ 6 m" },
        "623": { n: "Vrednost preklopa", t: "≥ 150 mm" },
        "624": { n: "Korak postavljanja pričvrsnih elemenata", t: "150-200 mm" },
        "625": { n: "Odstupanje od projektnog položaja u ravni spoja", t: "≤ 50 mm" },
        "626": { n: "Rastojanje do ivice konstrukcije u osnovi", t: "≥ 75 mm" },
        "627": { n: "Rastojanje do površine na koju se vrši montaža", t: "≤ 3 mm" },
        "628": { n: "Kvalitet spajanja cevčica", t: "Čvrsta veza elemenata" },
        "629": { n: "Rastojanje od mesta izlaska cevčica do spoja", t: "≥ 200 mm" },
        "630": { n: "Montaža kutija", t: "Postojanje kutija" },
        "631": { n: "Postavljanje čepova", t: "Postojanje čepova" },
        "632": { n: "Proporcija mešanja", t: "Kompletom (prema probnom uzorku). Pre samog utiskivanja rastvora u posebnu posudu se uzima proba i provera vreme geliranja" },
        "633": { n: "Prohodnost cevčica", t: "Potpuno, prema pritisku. Pre početka injektiranja potrebno je proveriti prohodnost cevčice vodom ili komprimovanim vazduhom iz kompresora" },
        "634": { n: "Pritisak injektiranja", t: "≤ 80 atm. Ne dozvoliti porast pritiska u sistemu iznad 80 atm.; po potrebi injektirati sa prekidima, održavajući pritisak u sistemu u opsegu od 20 do 40 atm" },
        "635": { n: "Potrošnja injekcione smole", t: "≤ 1,5 l/m.p." },
        "636": { n: "Izlazak injekcione smole iz ravni spoja", t: "50% dužine šava" },
        "637": { n: "Temperaturni režim", t: "Radovi se izvode pri temperaturi okoline i površine konstrukcije ne niže od +5°C." },
        "638": { n: "Zadelavanje otvora u betonu", t: "Pripremne mere za uklanjanje čepova i PVC cevčica i zapunjavanje otvora na celu debljinu konstrukcije reparaturnom masom" },
        "639": { n: "Pripremljenost površine podloge pre nanošenja", t: "Kvalitet površine (curci, ispupčenja) ne više od 2 mm. Dubina rupa ili kaverni dozvoljena ne veća od 5 mm; sa površine betona treba ukloniti cementno mleko, prljavštinu, mast, mrlje bitumena i ulja i druge nečistoće" },
        "640": { n: "Raspored spojeva i popuna šlica", t: "U vidu useka dimenzija 30x30 mm i njegovo popunjavanje specijalnom reparaturnom masom bez skupljanja. Obrada spojnica i popunjavanje useka reparaturnom masom" },
        "641": { n: "Debljina sloja", t: "Ne manje od 2 sloja. Drugi sloj se nanosi upravno na prvi, debljina jednog sloja ne manja od 1 mm" },
        "642": { n: "Poštovanje temperaturno-vlažnosnog režima nakon nanošenja", t: "Naredna dva dana temperatura vazduha i površine podloge mora biti ne niža od +5°C i ne viša od +30°C. Tokom očvršćavanja (najmanje 24 sata) površinu treba zaštititi pokrivanjem od kiše, dugotrajnog direktnog sunčevog zračenja i smrzavanja." },

