        "807": { n: "Kvalitetan malter za zidanje (marka, obradivost, dodaci protiv smrzavanja zimi)", t: "SP 82-101-98\nMarka mora odgovarati projektu. Dodavanje vode u pripremljeni malter se ne dozvoljava.\nUpotreba dodataka protiv smrzavanja.\nDeklaracija za malter." },
        "808": { n: "Vertikalni spojevi zidanja", t: "Tehnička karta\nVertikalno spajanje celih blokova izvodi se bez maltera, uklapanjem žleba i pera položenih blokova sa fugovanjem spojeva sa obe strane rastvorom. Vertikalni spoj se maltere samo u slučaju spajanja:\n- dva rezana bloka;\n- jednog rezanog i jednog celog bloka;\n- naslanjanja na skelet zgrade;" },
        "809": { n: "Debljina horizontalnih spojeva zidanja", t: "Tehnička karta\nDebljina horizontalnih spojnica mora biti 10 (+/-2) mm" },
        "810": { n: "Debljina donjeg izravnjavajućeg sloja zidanja prvog reda", t: "STO NOSTROY 2.9.136-2013, SP 70.13330.2012, tehnička karta. Za prvi red debljina izravnavajuće neprekidne spojnice maltera može varirati od 6 do 30 mm u zavisnosti od podloge." },
        "811": { n: "Ravnomerna popuna spojeva rastvorom", t: "SP 70.13330.2012 tač. 9.2.5, 9.2.6; Tehnička karta\nUključujući na naslanjanju krajnjih blokova na zidove po celoj dubini" },
        "812": { n: "Horizontalnost redova zidanja", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta, do 15 mm na 10 m dužine zida" },
        "813": { n: "Pravilnost vezivanja spojeva", t: "SP 70.13330.2012 tač. 9.2.1; Tehnička karta. Ne manje od 90 mm i ne više od 410 mm" },
        "814": { n: "Kontrola debljine zidova", t: "SP 70.13330.2012 tabela 9.8; Tehnička karta\nTolerancija ±15 mm." },
        "815": { n: "Popunjavanje zazora između poslednjeg reda zidanja i vertikalnih elemenata zgrade", t: "SP 70.13330.2012; Tehnička karta" },
        "816": { n: "Izrada nadvratnika/nadprozornika", t: "SP 70.13330.2012; Tehnička karta\nPri širini otvora do 1 m - oslanjanje levo i desno min. 100 mm. Ne preporučuje se da se pod oslonačkim delom nalazi vertikalni spoj pregradnih blokova.\nPri širini otvora do 1,1 m - oslanjanje levo i desno min. 100 mm, i po celoj dužini na armaturu klase AIII prema zidu sa obaveznim vertikalnim malterskim spojem. Armatura se pričvršćuje u armiranobetonski zid na preporučenu dubinu od 80 mm i uvlačenjem drugog kraja šipke u zidanje ne manje od 250 mm,\nPri širini do 1,6 m - stegnuti u zidanju po tipu konzole sa oslanjanjem ne manjim od 400 mm (1/3) sa donjim armiranjem metalnom armaturom klase A-III sa uvlačenjem krajnjih delova armaturne šipke ne manje od 250 mm u konstrukciju zidanja." },
        "817": { n: "Slabljenje kamenih konstrukcija - brazdama, šlicevima, nišama, otvorima", t: "SP 70.13330.2012 tač. 9.1.4; Tehnička karta" },
        "818": { n: "Vezivanje zidanja", t: "SP 70.13330.2012 tač. 9.2.1; Tehnička karta\nVezivanje zidanja sa pomeranjem reda za ½ dužine korišćenog materijala i ne manje od 1/3" },
        "819": { n: "Odstupanje ravni zidova i uglova od vertikale", t: "SP 70.13330.2012 (tabela 9.8); Tehnička karta\nTolerancija ne veća od 10 mm na celu visinu sprata" },
        "820": { n: "Neravnine na vertikalnoj površini zidanja.", t: "SP 70.13330.2012 (tabela 9.8); Tehnička karta\nTolerancija ne veća od 5 mm na celu visinu sprata" },
