        "1309": { n: "Ankerske pločice", t: "PIR. Debljina ≥1,5 mm, ugao savijanja ≥135°, pričvršćivanje svake pločice za zid sa 2 samorezna vijka. Materijal: nerđajući čelik (AISI 304, debljina ≥1,2 mm) ili pocinkovani čelik (debljina ≥1,5 mm)" },
        "1310": { n: "Odstupanje okvira", t: "GOST 34378-2018 Prilog Ž (kontrolna karta). Ne više od 1,5 mm na 1 m, ali ne više od 3 mm na celu dužinu" },
        "1311": { n: "Pričvrsni elementi", t: "GOST 30971-2012 G.1.3. Rastojanje od unutrašnjeg ugla okvira do učvršćenja =150 mm, od čvora impost spoja do elementa za učvršćenje - 120—180 mm, razmak ≤700 mm. Učvršćenje za ram - nerđajućim vijcima (Ø4–5 mm) kroz standardne otvore u profilu" },
        "1312": { n: "Tip pričvrsnice", t: "Prema projektu" },
        "1313": { n: "Tip pene", t: "GOST R 59599-2021 tač.5.3. Pena mora biti profesionalna (visoke ekspanzije, sa niskim koeficijentom sekundarne ekspanzije). Preporučuje se korišćenje poliuretanske pene sa adhezijom na PVC, beton, ciglu" },
        "1314": { n: "Uslovi nanošenja", t: "PIR. Temperatura: od +5°C do +30°C. Vlažnost vazduha: ≥40% (pri niskoj vlažnosti pena slabo polimerizuje)" },
        "1315": { n: "Zahtevi za nanošenje pene", t: "Montažni razmaci - širina 15-40 mm (GOST 30971-2012, tač. 5.2.1, tabela 2) Dubina ispune: ne manje od 90% širine spoja (radi izbegavanja šupljina). Ravnomerna ispuna. GOST 30971-2012 tač. 6.6 - Bez šupljina, pora, procepa. Što brža zaštita pene od UV zraka" },
        "1316": { n: "Izrada spoljašnjeg i unutrašnjeg sloja (zaptivanje)", t: "GOST 30971-2012 prilog A tač.2 i tač.4, neprekidnost/celovitost, odsustvo prslina, debljina sloja ne manja od 3 mm (ako je primenjen kit), preklop na okvir ne manji od 3 mm" },
        "1317": { n: "Celovitost proizvoda", t: "Interni standard kompanije (tabela 1 GOST 21519-2022 obuhvata pokazatelje ispitivanja, a ne vidljive defekte): odsustvo vidljivih defekata (prsline, odlomljeni delovi, ogrebotine)" },
        "1318": { n: "Prethodna regulacija", t: "GOST 21519-2022 tač. 8.3. Proveriti rad krila: otvaranje/zatvaranje glatko, bez zapinjanja (petostrukim otvaranjem i zatvaranjem)" },
        "1319": { n: "Zaštita proizvoda nakon montaže", t: "GOST 21519-2022 tač.5.7.1, GOST 34378-2018 tač.7.4 Proizvodi su zaštićeni (polikarbonat, privremeni ramovi, samolepljiva folija, premaz tipa smartskin)" },
        "1320": { n: "Postavljanje opšavnih limova", t: "PIR. Nagib ≥10%, prepust 30-50 mm, hermetičan spoj sa zidom, proizvodi bez oštećenja" },
        "1321": { n: "Postavljanje prozorske daske", t: "PIR. Isturenost van zida ≥50 mm, ne prekrivati >2/3 radijatora, nagib ≤1%, proizvodi bez oštećenja" },

        "1401": { n: "Dnevnik ulazne kontrole staklopaketa", t: "SP 48.13330.2019 tač. 3.1, Prilog B.1. Prema projektu. Proizvodi u skladu sa prihvaćenim etalonom. Provera formule staklopaketa." },
