        "1510": { n: "Broj i raspored podložaka", t: "Minimum 2 podmetača ispod vertikalnih stubova; Dodatni podmetači na svakih 600-700 mm; Obavezna ugradnja ispod grupe šarki. Za teška vrata (≥ 100 kg) - pojačano klinovanje. Po 2 klina sa svake strane vertikalnih stubova, 1 klin u gornjem horizontalnom delu\nRastojanje između klinova ≤ 600 mm." },
        "1511": { n: "Postavljanje ankera", t: "Broj tačaka učvršćenja: ne manje od 6 kom. (3 sa svake strane); Prečnik sidara: ne manje od 10 mm.\nDubina usidrenja: ne manje od 100 mm" },
        "1512": { n: "Montažna spojnica", t: "Interni standard kompanije Debljina spoja: 15-40 mm (u okviru normativnog opsega 10-60 mm, GOST R 71972-2025, tač.5.3.4/6.4); upotreba poliuretanske pene niske ekspanzije" },
        "1513": { n: "Zaptivanje (zaštita) spoja", t: "Prema projektu, uzorku etalona. Kit, traka" },
