        "1711": { n: "Upotreba vešaljki", t: "SP 163.1325800.2014 tač. 7.2.5.3, prema albumu KNAUF. Prema projektu. Korak vešalica: 900–1200 mm (maks. 1.2 m)\nPri opterećenju >15 kg/m²: smanjiti na 600 mm.\nZa višenivovske plafone: 600 mm" },
        "1712": { n: "Odstupanje skeleta po vertikali (zidovi)", t: "SP 163.1325800.2014, prema albumu KNAUF\nTolerancija: ≤2 mm/1 m, ali ≤10 mm na celu visinu" },
        "1713": { n: "Odstupanje skeleta po vertikali (plafoni)", t: "SP 163.1325800.2014, prema albumu KNAUF. Za jednonivovske plafone: ne više od 2 mm na 1 metar dužine, ali ne više od 10 mm na celu dužinu prostorije\nZa višenivovske i složene plafone: ne više od 1,5 mm na 1 metar. Za plafone pod farbanje: ne više od 1 mm na 1 metar. Za plafone sa osvetljenjem: ne više od 0,5 mm na 1 metar. Dozvoljene su lokalne neravnine do 1 mm pri proveri letvom\nZa krivolinijske elemente odstupanje ne veće od 3 mm od projektne linije. U zonama ugradnje svetiljki tolerancija se pooštrava za 30%" },
        "1714": { n: "Vezivanje profila u uglovima", t: "SP 163.1325800.2014, prema albumu KNAUF\nObavezno (album KNAUF)" },
