        "1912": { n: "Odsustvo mehurova", t: "Interni standard kompanije (procedura uklanjanja mehurova — tač. 7.6.8 SP 71.13330.2017; prijemna tač. 7.6.15 je isključena Izmenom br. 3, tolerancija \"≤2 kom./10 m²\" ne postoji u SP). Potpuno naleganje, lokalni defekti ≤2 kom./10 m²" },
        "1913": { n: "Obrada uglova", t: "SP 71.13330.2017 tač.7.6.10, tač.7.6.10. Čvrsto naleganje, odsustvo zazora >1 mm" },
