        "2001": { n: "Dnevnik ulazne kontrole korišćenih materijala", t: "SP 48.13330.2019 tač. 3.1, Prilog B.1" },
        "2002": { n: "Materijali se koriste u skladu s projektom", t: "SP 48.13330.2019 Prilog B, tač. B.1, stavka 7; Projekat" },
        "2003": { n: "Izvođački crteži izvedenih radova", t: "SP 70.13330 tač.3.5, 3.23" },
        "2004": { n: "Postojanje usaglašenog PIR", t: "SP 70.13330 tač.3.3" },
        "2005": { n: "Temperaturno-vlažnosni režim", t: "SP 71.13330.2017 tač. 7.1 . Završni radovi u prostorijama izvode se pri temperaturi okoline i završavanih površina od 5 °C do 30 °C, relativnoj vlažnosti vazduha ne većoj od 60%, ako proizvođač materijala nije naveo drugačije. Ovaj temperaturno-vlažnosni režim u prostoriji mora se održavati neprekidno tokom celog perioda izvođenja završnih radova i najmanje 2 dana pre početka i 12 dana posle završetka radova. Organizuje se grejanje ili zaštita od direktnih sunčevih zraka. Održati tehnološku pauzu u letnjem periodu najmanje četiri nedelje, u zimskom periodu najmanje 60 dana pri temperaturi od 0 °C do 5 °C posle skidanja oplate" },
        "2006": { n: "Prisustvo strana materija i uključaka na površini", t: "SP 71.13330.2017 tač.7.2. Ne dozvoljava se prisustvo stranih materija (prljavština, prskanje maltera, ostaci drveta, kalcijumske izloge)" },
        "2007": { n: "Prašinavost podloge", t: "SP 71.13330.2017 tač.7.2. Provlačiti rukom po površini i utvrditi prisustvo prašine i prljavštine. Ukloniti prašinu i prljavštinu" },
        "2008": { n: "Površinska čvrstoća podloge", t: "SP 71.13330.2017. Proverava se oštrom ivicom metalnog alata, uočava se odlomljivanje, opadanje. Odlepljujuće se deonice moraju ukloniti. Slabe podloge se čiste do čvrstog sloja i nanosi se grund GS 3." },
        "2009": { n: "Impregnacija podloge", t: "SP 71.13330.2017 tač.7.2.3. Podloge koje jako upijaju vlagu obraditi grundirajućim sastavom GS 1. Podloge koje ne upijaju - GS 4. U slučaju gipsanog maltera naneti mineralni grund." },
        "2010": { n: "Kontrola šare, faktura, teksture, dimenzija", t: "SP 71.13330.2017 tač. 7.4.9. Obradu deonice vršiti sa usklađivanjem cele šare polja oblaganja u skladu sa zahtevima projektne dokumentacije" },
        "2011": { n: "Upotreba lepljivog sastava", t: "SP 71.13330.2017 tač. 7.4.5. Pre početka radova provera usklađenosti lepljive smeše sa tipom pokrivača" },
        "2012": { n: "Nanošenje lepljivog sastava", t: "SP 71.13330.2017 tač. 7.4.6. Neophodno je obezbediti prostor bez praznina između zida i pločice. Površina deonice ne prelazi otvoreno vreme smeše. (Kod pločica >900 cm² lepak se nanosi i na pločicu)" },
        "2013": { n: "Čišćenje oblaganja", t: "SP 71.13330.2017 tač. 7.4.12. Nakon oblaganja površine moraju biti odmah očišćene od izliva maltera." },
        "2014": { n: "Izrada spojeva", t: "SP 71.13330.2017 tač. 7.4.13. Spojevi oblaganja moraju biti ravni, jednake širine. Popunjeni posebnim materijalima za spojeve (fugama) prema GOST R 58271" },
        "2015": { n: "Ogledalska, poliranje", t: "\"SP 71.13330.2017\" tabela 7.6\nOdstupanje od vertikale ne veće od 2 mm na 1 m dužine. (4 mm po spratu)\nOdstupanja položaja spojnica od vertikale i horizontale ne veća od 1,5 mm na 1 m dužine.\nOdstupanja širine spojnica ne veća od +/- 0,5mm.\nNepoklapanje profila na spojevima arhitektonsko-građevinskih elemenata i spojnica ne veće od 0,5mm.\nNeravnine ravni obloge (pri kontroli dvometarskom letvom) ne veće od 2 mm." },
        "2016": { n: "Brušena, tačkasta, brdovita, brazdovita", t: "Interni standard kompanije (SP 71.13330.2017, tabela 7.6 za ovu fakturu ne propisuje odstupanje širine spoja — crta u tabeli): Odstupanje od vertikale ne veće od 3 mm na 1 m (8 mm na sprat). Odstupanja spojeva ne veća od 3 mm na 1 m. Odstupanja širine spojeva ne veća od +/- 1 mm. Neravnine ravni (letva 2 m) ne veće od 4 mm." },
        "2017": { n: "Faktura tipa stena", t: "\"SP 71.13330.2017\" tabela 7.6\nOdstupanja položaja spojnica od vertikale i horizontale ne veća od 3 mm na 1 m dužine.\nNepoklapanje profila na spojevima arhitektonsko-građevinskih elemenata i spojnica ne veće od 2 mm. Odstupanja širine spojnica ne veća od +/- 2mm" },
        "2018": { n: "Od granita i veštačkog kamena", t: "SP 71.13330.2017, tabela 7.6 (od granita i veštačkog kamena): Odstupanja širine spojeva ne veća od +/- 0,5 mm" },
        "2019": { n: "Od mermera", t: "SP 71.13330.2017, tabela 7.6 (od mermera): Odstupanja širine spojeva ne veća od +/- 0,5 mm" },
        "2020": { n: "Od keramičkih, staklo-keramičkih proizvoda", t: "\"SP 71.13330.2017\" tabela 7.6\nOdstupanje od vertikale ne veće od 1,5 mm na 1 m dužine. (4 mm po spratu)\nOdstupanja položaja spojnica od vertikale i horizontale ne veća od 1,5 mm na 1 m dužine.\nOdstupanja širine spojnica ne veća od +/- 0,5mm.\nNepoklapanje profila na spojevima arhitektonsko-građevinskih elemenata i spojnica ne veće od 3 mm na 1 m.\nNeravnine ravni obloge (pri kontroli dvometarskom letvom) ne veće od 2 mm" },

