        "2917": { n: "Odstupanje linija ravni preseka od vertikale ili projektnog nagiba na celoj visini: zidova koji nose monolitne ploče, ≤15 mm", t: "SP 70.13330.2012 tabela 5.12" },
        "2918": { n: "Odstupanje linija ravni preseka od vertikale zidova koji nose montažne gredne konstrukcije, ≤10 mm", t: "SP 70.13330.2012 tabela 5.12" },
        "2919": { n: "Lokalne neravnine površine betona pri proveri dvometarskom letvom, osim oslonačkih površina, ≤5 mm", t: "SP 70.13330.2012 tabela 5.12" },
        "2920": { n: "Odstupanje horizontalnih ravni na celoj dužini deonice koja se proverava, 20 mm", t: "SP 70.13330.2012 tabela 5.12" },
        "2921": { n: "Odstupanje dužina ili raspona elemenata, svetlih mera, ±20 mm", t: "SP 70.13330.2012 tabela 5.12" },
        "2922": { n: "Dimenzija poprečnog preseka", t: "h<200: +6 mm; h=400: -3 +11 mm; h>2000: -9/+25 mm. Pri međuvrednostima h veličina tolerancije usvaja se interpolacijom.\nSP 70.13330.2012 tabela 5.12" },
