        "2926": { n: "Rupice, odlomljeni delovi betona", t: "≤15 mm i dubine ≤5 mm, odlomi rebara betona ≤10 mm. SP 70.13330.2012 tač.5.18.4" },
        "2927": { n: "Deonice nesabijenog betona, nisu dozvoljene", t: "SP 70.13330.2012 tač.5.18.4, Prilog H" },
